import random
from dateutil.relativedelta import relativedelta

random.seed(3)
bad = []
for i in range(20000):
    kw = {}
    for k, lim in (("days", 100), ("hours", 100), ("minutes", 200), ("seconds", 200), ("microseconds", 3e6)):
        if random.random() < 0.6:
            kw[k] = random.choice([random.randint(-lim, lim), random.uniform(-lim, lim)])
    if random.random() < 0.3:
        kw["months"] = random.randint(-40, 40)
    rd = relativedelta(**kw)
    checks = [("microseconds", 999999), ("seconds", 59), ("minutes", 59), ("hours", 23), ("months", 11)]
    for attr, lim in checks:
        v = getattr(rd, attr)
        if abs(v) > lim:
            bad.append(("range", kw, attr, v))
    # normalized must be all-integer relative attrs
    n = rd.normalized()
    for attr in ("years", "months", "days", "hours", "minutes", "seconds", "microseconds"):
        v = getattr(n, attr)
        if not isinstance(v, int):
            bad.append(("nonint", kw, attr, v))
    # normalized must be equivalent when added
    import datetime
    now = datetime.datetime(2003, 9, 17, 20, 54, 47, 282310)
    if now + rd != now + n:
        bad.append(("norm-equiv", kw, now + rd, now + n))
print("violations:", len(bad))
seen = set()
for b in bad:
    if b[0] not in seen:
        seen.add(b[0]); print(b)
for b in bad[:15]:
    print(b)
